def extract_even(data):
    def process_element(element):
        if isinstance(element, tuple):
            # Recursively process nested tuples
            processed = tuple(process_element(e) for e in element if isinstance(e, int) and e % 2 == 0 or isinstance(e, tuple))
            return processed
        elif isinstance(element, int) and element % 2 == 0:
            # Keep even integers
            return element
        return None  # Remove uneven elements or non-integer elements

    # Process the outermost tuple and filter out `None` results
    return tuple(x for x in (process_element(el) for el in data) if x is not None)

# Example test
assert extract_even((4, 5, (7, 6, (2, 4)), 6, 8)) == (4, (6, (2, 4)), 6, 8)
```

